(function(){const T=window.TABLES_EXTRA=window.TABLES_EXTRA||{};Object.assign(T,{"trap2": {"n": "Ловушки подземелья", "d": "к20", "rows": [[1, "Падающая решётка: плита под ногами опускает решётку позади отряда, разделяя его. Заметить: Внимательность Сл 13. Поднять: Сила (Атлетика) Сл 17."], [2, "Маятник-секира: качается поперёк коридора. Спас ЛОВ Сл 14 или 3к10 рубящего. Пройти можно, рассчитав ритм (Анализ Сл 12)."], [3, "Ложный пол над ямой 6 м с кольями: 2к6 падение + 2к10 колющего. Заметить: Внимательность Сл 14."], [4, "Ядовитые иглы в замке сундука: Тел Сл 13 или 2к10 яда и отравлен на 1 час. Обезвредить: воровские инструменты Сл 15."], [5, "Потолок опускается: 4 раунда до сдавливания (10к10). Остановить: заклинить механизм (Сила Сл 16) или найти рычаг (Анализ Сл 15)."], [6, "Руна огня на двери: при открытии без пароля — 5к8 огнём в радиусе 6 м, спас ЛОВ Сл 15 половина. Обнаружение магии выявляет."], [7, "Затопляемая комната: двери запираются, вода поднимается за 5 раундов. Выход — сливная решётка под водой (Атлетика Сл 14)."], [8, "Катящийся валун: спас ЛОВ Сл 15 или 4к10 дробящего и сбит с ног. Можно спрятаться в нишу (Внимательность Сл 12, чтобы заметить)."], [9, "Зеркало-ловушка: смотрящий проходит спас ХАР Сл 15 или заточён в зеркале до разбивания (КД 13, хиты 10)."], [10, "Клей на ступенях: существо прилипает (опутан), освобождение Сила Сл 14; через 1 раунд из стен выходят стрелы (+6, 1к8)."], [11, "Газовые форсунки: облако усыпляющего газа 6 м, спас ТЕЛ Сл 13 или без сознания 10 минут."], [12, "Иллюзорная стена над пропастью: выглядит как проход. Анализ Сл 15 или касание шестом раскрывает."], [13, "Вращающаяся комната: каждые 2 раунда двери меняют место. Запомнить порядок — Анализ Сл 13; ошибка выводит к стражу."], [14, "Электрическая решётка пола: металл на ногах — 2к8 электричества за каждые 1,5 м. Деревянные доски обходят ловушку."], [15, "Сеть с потолка: опутывает всех в квадрате 3 м (Сила Сл 12 освободиться, КД 10, хиты 5 у сети) и звонит колокол тревоги."], [16, "Ложное сокровище: монеты — мимики-рои (2 роя насекомых в облике монет). Внимательность Сл 15 замечает движение."], [17, "Дыхательная плита: на плите статуя дракона выдыхает кислоту — линия 9 м, спас ЛОВ Сл 14, 4к6 кислоты."], [18, "Песочные часы: в комнате песок сыплется с потолка; за 6 раундов он заполняет помещение. Перевернуть часы на алтаре — остановит."], [19, "Проклятая монета на алтаре: взявший проходит спас МДР Сл 14 или проклят (помеха на проверки, пока не вернёт)."], [20, "Шипастые стены сходятся: 3 раунда, затем 6к10 колющего. Упор шестом даёт ещё 2 раунда; рычаг за ложным камнем."]]}, "puzzle": {"n": "Головоломки", "d": "к12", "rows": [[1, "Четыре статуи стихий и пустой постамент: нужно повернуть статуи лицом к их противоположностям (огонь—вода, земля—воздух)."], [2, "Плиты с буквами на полу: ступать можно только на буквы ответа на надпись над входом («Что всегда приходит, но никогда не наступает?» — ЗАВТРА)."], [3, "Весы и гири: дверь откроется, если на чашах будет равный вес; гирь 5 (1, 3, 4, 7, 9 кг), нужно уравновесить 12 кг: 9+3 против 7+4+1."], [4, "Три рычага и три лампы в соседней комнате: можно зайти туда один раз. Решение: включить первый надолго, выключить, включить второй; тёплая лампа — первый."], [5, "Мозаика с недостающими плитками: плитки разбросаны по подземелью; каждая найдена после победы над стражем."], [6, "Говорящая дверь: откроется тому, кто честно назовёт свой главный страх (проверка Проницательности двери Сл 15 против лжи)."], [7, "Лабиринт зеркал: настоящий путь виден только в отражении свечи, которую нужно нести перед собой."], [8, "Колокола разных тонов: сыграть мелодию с фрески над входом; ошибка вызывает звуковой удар 2к6."], [9, "Песочный стол с картой: двигая фигурки королевств как в легенде на стене, открываются тайные ниши."], [10, "Пять сосудов с цветными жидкостями и надпись: «Смешай закат». Решение — красный и жёлтый; иное смешение — облако газа."], [11, "Звёздный потолок: передвинуть звёзды, чтобы восстановить созвездие с герба на двери."], [12, "Сундук с семью замками и одним ключом: ключ меняет форму, если сказать вслух номер замка на языке хозяина (Анализ Сл 14 узнать язык)."]]}, "riddle2": {"n": "Загадки (с ответом)", "d": "к20", "rows": [[1, "«Чем больше сушишь, тем мокрее становлюсь». — Полотенце."], [2, "«Без рук, без ног, а ворота открывает». — Ветер."], [3, "«Кто говорит на всех языках?» — Эхо."], [4, "«Сидит дед, во сто шуб одет; кто его раздевает, тот слёзы проливает». — Лук."], [5, "«Чем больше в ней дыр, тем она легче держит». — Сеть."], [6, "«Меня ломают, ещё не назвав». — Тишина."], [7, "«Днём спит, ночью летает, прохожих пугает». — Сова."], [8, "«Не огонь, а жжётся». — Крапива."], [9, "«У меня есть шея, но нет головы». — Бутылка."], [10, "«Что можно поймать, но нельзя бросить?» — Простуду."], [11, "«Течёт, течёт — не вытечет; бежит, бежит — не выбежит». — Река."], [12, "«Один отец, двенадцать сыновей, у каждого тридцать дочерей — наполовину белых, наполовину чёрных». — Год."], [13, "«Я лёгкий, как перо, но и силач не удержит меня долго». — Дыхание."], [14, "«Всё сжирает: зверя, птицу, лес, цветок, сталь и камень». — Время."], [15, "«Что идёт вверх, но никогда не опускается?» — Возраст."], [16, "«Чем больше берёшь, тем больше оставляешь». — Шаги."], [17, "«Два конца, два кольца, посредине гвоздик». — Ножницы."], [18, "«Утром на четырёх, днём на двух, вечером на трёх». — Человек."], [19, "«Кто приходит ночью без зова и уходит утром без следа?» — Сон."], [20, "«Чем меньше её, тем больше видно». — Темнота (нет её — светло)."]]}});})();

