 for(let i=0;i<n*1.2;i++){c.fillStyle='rgba(20,10,4,0.35)';MD.ell(c,x+rnd()*w,y+rnd()*h,S*0.02,S*0.012,hor?0:Math.PI/2);c.fill()}
