map(c,S,x,y,a,rnd){c.save();c.translate(x,y);c.rotate(a);c.fillStyle='#d9c79a';c.fillRect(-S*.3,-S*.2,S*.6,S*.4);c.strokeStyle='rgba(90,60,30,.7)';c.lineWidth=S*.012;c.beginPath();c.moveTo(-S*.25,S*.05);for(let i=0;i<6;i++)c.lineTo(-S*.25+i*S*.1,(rnd()-.5)*S*.25);c.stroke();c.strokeStyle='rgba(150,30,20,.8)';c.beginPath();c.moveTo(S*.08,-S*.05);c.lineTo(S*.14,S*.01);c.moveTo(S*.14,-S*.05);c.lineTo(S*.08,S*.01);c.stroke();ink(c,S,.015);c.strokeRect(-S*.3,-S*.2,S*.6,S*.4);c.restore()},
