  if(bb==='соломенный тюфяк'){shadow(c,S,()=>{rr(c,S*.1,S*.15,W-S*.2,H-S*.3,S*.15);c.fillStyle='#b8a060';c.fill()});c.strokeStyle='rgba(120,90,30,.7)';c.lineWidth=S*.012;for(let i=0;i<70;i++){const x=S*.15+rnd()*(W-S*.3),y=S*.2+rnd()*(H-S*.4);c.beginPath();c.moveTo(x,y);c.lineTo(x+(rnd()-.5)*S*.2,y+(rnd()-.5)*S*.1);c.stroke()}blanket(c,S,S*.15,H*.45,W-S*.3,H*.45,b,rnd);return}
