door('reinforced','Окованная дверь',['подземелье','крепость'],1,(c,S,rnd,W)=>{wood(c,S,S*.18,S*.36,W-S*.36,S*.28,P.dwood,rnd,'v',4);c.fillStyle='#45484d';[S*.3,W-S*.36].forEach(x=>c.fillRect(x,S*.36,S*.06,S*.28));c.fillStyle='#8a8f96';for(let x=S*.24;x<W-S*.2;x+=S*.09){circ(c,x,S*.4,S*.015);c.fill();circ(c,x,S*.6,S*.015);c.fill()}});
