const figure=(c,S,x,y,k,mat,item)=>{const r=S*.18*k;ell(c,x,y+r*.15,r*1.25,r*.6);c.fillStyle=lg(c,x-r,y,x+r,y,[mat[3],mat[1]]);c.fill();ink(c,S,.02);c.stroke();circ(c,x,y-r*.1,r*.45);c.fillStyle=rg(c,x-r*.15,y-r*.25,0,r*.5,[mat[3],mat[1]]);c.fill();ink(c,S,.02);c.stroke();
 if(item==='меч'){c.fillStyle=mat[3];c.fillRect(x-r*.07,y+r*.4,r*.14,r*1.1);c.fillRect(x-r*.35,y+r*.35,r*.7,r*.1);ink(c,S,.012);c.strokeRect(x-r*.07,y+r*.4,r*.14,r*1.1)}
 if(item==='посох'){c.strokeStyle=mat[1];c.lineWidth=r*.12;c.beginPath();c.moveTo(x+r*1.1,y-r*.8);c.lineTo(x+r*1.1,y+r*1.1);c.stroke();circ(c,x+r*1.1,y-r*.8,r*.2);c.fillStyle=mat[3];c.fill();ink(c,S,.012);c.stroke()}
 if(item==='книга'){rr(c,x-r*.35,y+r*.45,r*.7,r*.4,r*.05);c.fillStyle=mat[2];c.fill();ink(c,S,.012);c.stroke()}
 if(item==='копьё'){c.strokeStyle=mat[1];c.lineWidth=r*.1;c.beginPath();c.moveTo(x-r*1.1,y-r*1.4);c.lineTo(x-r*1.1,y+r*1.2);c.stroke();poly(c,[[x-r*1.1,y-r*1.7],[x-r*.95,y-r*1.35],[x-r*1.25,y-r*1.35]]);c.fillStyle=mat[3];c.fill()}
 if(item==='корона'){c.fillStyle='#d8b440';for(let i=0;i<5;i++){const a=i/5*PI*2;poly(c,[[x+Math.cos(a)*r*.35,y-r*.1+Math.sin(a)*r*.35],[x+Math.cos(a+.3)*r*.5,y-r*.1+Math.sin(a+.3)*r*.5],[x+Math.cos(a+.6)*r*.35,y-r*.1+Math.sin(a+.6)*r*.35]]);c.fill()}}
 if(item==='крылья'||item==='крылья-демона'){[-1,1].forEach(s=>{c.beginPath();c.moveTo(x+s*r*.8,y);if(item==='крылья'){c.quadraticCurveTo(x+s*r*2,y-r*1.2,x+s*r*2.2,y+r*.4);c.quadraticCurveTo(x+s*r*1.5,y+r*.2,x+s*r*.8,y+r*.4)}else{c.lineTo(x+s*r*2.1,y-r*1);c.lineTo(x+s*r*1.8,y+r*.1);c.lineTo(x+s*r*2.2,y+r*.6);c.lineTo(x+s*r*1.3,y+r*.3);c.lineTo(x+s*r*.8,y+r*.4)}c.closePath();c.fillStyle=mat[2];c.fill();ink(c,S,.015);c.stroke()})}
 if(item==='рога'){[-1,1].forEach(s=>{c.beginPath();c.moveTo(x+s*r*.25,y-r*.3);c.quadraticCurveTo(x+s*r*.7,y-r*.7,x+s*r*.5,y-r*1.1);c.lineWidth=r*.12;c.strokeStyle=mat[0];c.stroke()})}
 if(item==='щит'){circ(c,x-r*.9,y+r*.3,r*.5);c.fillStyle=mat[2];c.fill();ink(c,S,.015);c.stroke();circ(c,x-r*.9,y+r*.3,r*.15);c.fillStyle=mat[0];c.fill()}
 if(item==='чаша'){circ(c,x,y+r*.55,r*.25);c.fillStyle='#d8b440';c.fill();ink(c,S,.012);c.stroke()}};
