const MCOL={'тайный синий':'#5ab0ff','адский красный':'#ff4a20','мертвенный зелёный':'#6aff5a','небесный золотой':'#ffd860','теневой фиолетовый':'#b070ff'};
const shapes={'пентаграмма':(c,R,n)=>{c.beginPath();for(let i=0;i<=5;i++){const a=-PI/2+i*PI*4/5;c.lineTo(Math.cos(a)*R,Math.sin(a)*R)}c.stroke()},'гексаграмма':(c,R)=>{[0,PI].forEach(o=>{c.beginPath();for(let i=0;i<=3;i++){const a=-PI/2+o+i*PI*2/3;c.lineTo(Math.cos(a)*R,Math.sin(a)*R)}c.stroke()})},'треугольник':(c,R)=>{c.beginPath();for(let i=0;i<=3;i++){const a=-PI/2+i*PI*2/3;c.lineTo(Math.cos(a)*R,Math.sin(a)*R)}c.stroke();circ(c,0,0,R*.5);c.stroke()},'квадрат в круге':(c,R)=>{[0,PI/4].forEach(o=>{c.beginPath();for(let i=0;i<=4;i++){const a=o+i*PI/2;c.lineTo(Math.cos(a)*R,Math.sin(a)*R)}c.stroke()})},'спираль':(c,R)=>{c.beginPath();for(let a=0;a<PI*6;a+=.1){const r=R*a/(PI*6);c.lineTo(Math.cos(a)*r,Math.sin(a)*r)}c.stroke()},'глаз':(c,R)=>{c.beginPath();c.moveTo(-R,0);c.quadraticCurveTo(0,-R*.9,R,0);c.quadraticCurveTo(0,R*.9,-R,0);c.stroke();circ(c,0,0,R*.3);c.stroke();circ(c,0,0,R*.1);c.fill()}};
const glyph=(c,S,x,y,a,rnd)=>{c.save();c.translate(x,y);c.rotate(a);c.beginPath();const k=rnd()*4|0;const s=S*.06;if(k===0){c.moveTo(-s,-s);c.lineTo(0,s);c.lineTo(s,-s)}else if(k===1){c.moveTo(-s,0);c.lineTo(s,0);c.moveTo(0,-s);c.lineTo(0,s);c.moveTo(-s,-s);c.lineTo(-s*.4,-s)}else if(k===2){c.arc(0,0,s*.7,0,PI*1.5)}else{c.moveTo(-s,s);c.lineTo(0,-s);c.lineTo(s,s);c.moveTo(-s*.5,0);c.lineTo(s*.5,0)}c.stroke();c.restore()};
for(const sh in shapes)for(const cl in MCOL){const col=MCOL[cl];add('circle-'+slug(sh)+'-'+slug(cl),'Магический круг: '+sh+' ('+cl+')','Магия',['башня мага','логово культа','ритуальный зал'],3,3,false,'floor',(c,S,rnd,p,W)=>{c.save();c.translate(W/2,W/2);const R=W*.46;glow(c,0,0,R*1.1,col.replace('#','rgba(').length?'rgba(255,255,255,0.0)':'');c.shadowColor=col;c.shadowBlur=S*.25;c.strokeStyle=col;c.fillStyle=col;c.lineWidth=S*.04;circ(c,0,0,R);c.stroke();c.lineWidth=S*.02;circ(c,0,0,R*.86);c.stroke();for(let i=0;i<18;i++){const a=i/18*PI*2+PI/18;glyph(c,S,Math.cos(a)*R*.93,Math.sin(a)*R*.93,a+PI/2,rnd)}c.lineWidth=S*.03;shapes[sh](c,R*.84);c.restore();const g=c.createRadialGradient(W/2,W/2,0,W/2,W/2,W*.5);g.addColorStop(0,col+'40');g.addColorStop(1,col+'00');c.fillStyle=g;circ(c,W/2,W/2,W*.5);c.fill()})}
