const LIQ={'вода':['#4a8090','#1a3a4a','rgba(200,240,255,.35)'],'болотная жижа':['#5a6a2a','#2a3010','rgba(200,220,120,.25)'],'лава':['#ffb030','#8a1e06','rgba(255,200,80,.5)'],'кислота':['#c8ff40','#3a6a08','rgba(230,255,150,.4)'],'кровь':['#a8201a','#3a0404','rgba(255,120,120,.25)'],'слизь':['#a050c0','#3a1048','rgba(230,180,255,.3)'],'святая вода':['#e0f8ff','#5aa0d0','rgba(255,255,255,.5)'],'чёрная вода':['#2a3040','#050608','rgba(150,150,200,.2)']};
