M.SKEL=(c,S,x,y,k,rnd,pose)=>{const s=S*k;const w=s*.045;const H=[x,y-s*.55];T.skull(c,S,H[0],H[1]-s*.05,k*1.1);bone(c,S,x,y-s*.45,x,y,w);for(let i=0;i<4;i++){c.strokeStyle='#d8cfb0';c.lineWidth=w*.7;c.beginPath();c.ellipse(x,y-s*(.36-i*.08),s*.15,s*.03,0,0,PI*2);c.stroke()}const sh=[x,y-s*.42];const a1=pose==='sit'?[x-s*.28,y-s*.05]:[x-s*.3,y-s*.15],a2=pose==='sit'?[x+s*.28,y-s*.05]:[x+s*.22+rnd()*s*.1,y-s*.5];bone(c,S,sh[0]-s*.12,sh[1],a1[0],a1[1],w);bone(c,S,sh[0]+s*.12,sh[1],a2[0],a2[1],w);ell(c,x,y,s*.12,s*.06);c.fillStyle='#c8bea0';c.fill();ink(c,S,.012);c.stroke();const l1=pose==='sit'?[x-s*.2,y+s*.25]:[x-s*.12,y+s*.5],l2=pose==='sit'?[x+s*.2,y+s*.25]:[x+s*.15+rnd()*s*.1,y+s*.48];bone(c,S,x-s*.07,y,l1[0],l1[1],w*1.1);bone(c,S,x+s*.07,y,l2[0],l2[1],w*1.1);if(pose==='sit'){bone(c,S,l1[0],l1[1],l1[0]-s*.02,l1[1]+s*.25,w);bone(c,S,l2[0],l2[1],l2[0]+s*.02,l2[1]+s*.25,w)}};
