 'солнце':(c,s,col)=>{c.fillStyle=col;circ(c,0,0,s*.2);c.fill();c.strokeStyle=col;c.lineWidth=s*.06;for(let i=0;i<12;i++){const a=i/12*PI*2;c.beginPath();c.moveTo(Math.cos(a)*s*.27,Math.sin(a)*s*.27);c.lineTo(Math.cos(a)*s*.42,Math.sin(a)*s*.42);c.stroke()}},
