for(const o in ORE){mine('vein-'+slug(o),'Рудная жила: '+o,2,1,true,(c,S,rnd,p,W)=>{stoneBlock(c,S,0,0,W,S*.45,P.dstone,rnd);c.strokeStyle=ORE[o][1];c.lineWidth=S*.06;c.beginPath();c.moveTo(0,S*.25);c.bezierCurveTo(W*.3,S*.05,W*.6,S*.4,W,S*.2);c.stroke();for(let i=0;i<10;i++){const x=rnd()*W,y=S*(.1+rnd()*.3);poly(c,[[x,y-S*.03],[x+S*.04,y],[x,y+S*.03],[x-S*.04,y]]);c.fillStyle=ORE[o][i%2];c.fill()}if(o==='мифрил'||o==='самоцветы')glow(c,W/2,S*.25,S*.8,'rgba(200,220,255,.25)')});
 mine('ore-'+slug(o),'Куча руды: '+o,1,1,false,(c,S,rnd)=>{for(let i=0;i<12;i++){const x=S*(.25+rnd()*.5),y=S*(.25+rnd()*.5);blob(c,x,y,S*(.05+rnd()*.06),rnd,6,.4);c.fillStyle=i%3?'#5a5751':ORE[o][0];c.fill();ink(c,S,.01);c.stroke()}})}
mine('pick-rack','Стойка с кирками',1,1,true,(c,S,rnd)=>{wood(c,S,S*.1,S*.4,S*.8,S*.2,P.dwood,rnd,'h',1);for(let i=0;i<3;i++){const x=S*(.25+i*.25);c.fillStyle='#6e5034';c.fillRect(x-S*.02,S*.15,S*.04,S*.7);c.strokeStyle='#63676d';c.lineWidth=S*.04;c.beginPath();c.moveTo(x-S*.12,S*.22);c.quadraticCurveTo(x,S*.12,x+S*.12,S*.22);c.stroke()}},'Механизмы');
mine('ale-keg-giant','Гигантская бочка эля',2,2,true,(c,S,rnd,p,W)=>{M.T&&0;const pal=P.wood;shadow(c,S,()=>{circ(c,W/2,W/2,S*.9);c.fillStyle=pal[1];c.fill()});c.save();circ(c,W/2,W/2,S*.9);c.clip();wood(c,S,0,0,W,W,pal,rnd,'v',9);c.restore();circ(c,W/2,W/2,S*.9);c.strokeStyle='#2b2d30';c.lineWidth=S*.08;c.stroke();circ(c,W/2,W/2,S*.7);c.lineWidth=S*.04;c.stroke();c.fillStyle='#c49a3c';c.font=`bold ${S*.5}px serif`;c.textAlign='center';c.textBaseline='middle';c.fillText('ᚱ',W/2,W/2)},'Ёмкости');
mine('rune-brazier','Рунная жаровня дварфов',1,1,true,(c,S,rnd)=>{const pts=[];for(let i=0;i<6;i++){const a=i/6*PI*2;pts.push([S/2+Math.cos(a)*S*.42,S/2+Math.sin(a)*S*.42])}poly(c,pts);c.fillStyle='#45484d';c.fill();ink(c,S);c.stroke();c.strokeStyle='#c49a3c';c.lineWidth=S*.02;pts.forEach(q=>{c.beginPath();c.moveTo(q[0]*.8+S*.1,q[1]*.8+S*.1);c.lineTo(q[0]*.7+S*.15,q[1]*.7+S*.15);c.stroke()});circ(c,S/2,S/2,S*.25);c.fillStyle=rg(c,S/2,S/2,0,S*.25,['#ffe080','#ff7a10','#4a1004']);c.fill();glow(c,S/2,S/2,S,'rgba(255,140,40,.35)')},'Свет');
mine('pillar-carved','Резная колонна дварфов',1,1,true,(c,S,rnd)=>{const pts=[];for(let i=0;i<8;i++){const a=PI/8+i*PI/4;pts.push([S/2+Math.cos(a)*S*.44,S/2+Math.sin(a)*S*.44])}poly(c,pts);c.fillStyle=lg(c,0,0,S,S,['#8a867e','#3a3940']);c.fill();ink(c,S);c.stroke();circ(c,S/2,S/2,S*.25);c.strokeStyle='#c49a3c';c.lineWidth=S*.03;c.stroke();c.beginPath();for(let i=0;i<4;i++){const a=i/4*PI*2+PI/4;c.moveTo(S/2,S/2);c.lineTo(S/2+Math.cos(a)*S*.25,S/2+Math.sin(a)*S*.25)}c.stroke()},'Статуи');
mine('lava-channel','Лавовый жёлоб кузни',3,1,false,(c,S,rnd,p,W)=>{stoneBlock(c,S,0,S*.2,W,S*.6,P.dstone,rnd);c.fillStyle=lg(c,0,S*.3,0,S*.7,['#ffb030','#d8520e','#8a1e06']);c.fillRect(0,S*.32,W,S*.36);c.fillStyle='rgba(50,15,5,.6)';for(let i=0;i<8;i++){blob(c,rnd()*W,S/2,S*.08,rnd,6,.5);c.fill()}glow(c,W/2,S/2,S*1.5,'rgba(255,100,20,.3)')},'Вода и лава');
mine('mithril-anvil','Мифриловая наковальня',1,1,true,(c,S,rnd)=>{stoneBlock(c,S,S*.2,S*.2,S*.6,S*.6,P.dstone,rnd);c.beginPath();c.moveTo(S*.08,S*.5);c.quadraticCurveTo(S*.2,S*.38,S*.3,S*.38);c.lineTo(S*.82,S*.38);c.lineTo(S*.82,S*.62);c.lineTo(S*.3,S*.62);c.quadraticCurveTo(S*.2,S*.62,S*.08,S*.5);c.fillStyle=lg(c,0,S*.38,0,S*.62,['#ffffff','#a0c0e0','#5a7aa0']);c.fill();ink(c,S,.02);c.stroke();glow(c,S/2,S/2,S*.6,'rgba(200,230,255,.35)')},'Механизмы');
mine('mushroom-farm','Грибная ферма подземья',2,2,false,(c,S,rnd,p,W)=>{c.fillStyle='rgba(60,40,30,.6)';c.fillRect(S*.05,S*.05,W-S*.1,W-S*.1);for(let i=0;i<4;i++)for(let j=0;j<4;j++){const x=S*(.3+i*.47),y=S*(.3+j*.47),r=S*(.1+rnd()*.06);circ(c,x,y,r);c.fillStyle=rg(c,x,y,0,r,['#e0c8ff','#7a4aa8']);c.fill();ink(c,S,.012);c.stroke()}},'Природа');
