const inf=(id,n,w,h,solid,f,cat,layer)=>add('inf-'+id,n,cat||'Культ',['инфернальное','бездна','логово демона'],w,h,solid,layer||'object',f);
inf('brimstone','Серные шипы',1,1,true,(c,S,rnd)=>{for(let i=0;i<6;i++){const x=S*(.2+rnd()*.6),y=S*(.2+rnd()*.6),r=S*(.08+rnd()*.1);for(let k=3;k>0;k--){blob(c,x,y,r*k/3,rnd,6,.4);c.fillStyle=['#e8c040','#8a4a10','#2a1008'][k-1];c.fill()}}glow(c,S/2,S/2,S*.6,'rgba(255,90,20,.25)')},'Природа');
inf('hooks','Цепи с крюками',1,1,false,(c,S,rnd)=>{c.strokeStyle='#45484d';c.lineWidth=S*.02;for(let i=0;i<4;i++){const x=S*(.2+i*.2);c.beginPath();for(let y=0;y<S*.7;y+=S*.06){c.moveTo(x,y);c.lineTo(x,y+S*.04)}c.stroke();c.lineWidth=S*.03;c.beginPath();c.arc(x+S*.04,S*.75,S*.05,PI,PI*.2,true);c.stroke();c.lineWidth=S*.02}c.fillStyle='rgba(110,10,8,.6)';circ(c,S*.45,S*.85,S*.06);c.fill()},'Механизмы','top');
inf('soul-cage','Клетка душ',1,1,true,(c,S,rnd)=>{glow(c,S/2,S/2,S*.6,'rgba(120,255,200,.4)');circ(c,S/2,S/2,S*.35);c.strokeStyle='#22242a';c.lineWidth=S*.04;c.stroke();for(let i=0;i<8;i++){const a=i/8*PI*2;c.beginPath();c.moveTo(S/2,S/2);c.lineTo(S/2+Math.cos(a)*S*.35,S/2+Math.sin(a)*S*.35);c.lineWidth=S*.02;c.stroke()}for(let i=0;i<3;i++){c.fillStyle='rgba(200,255,230,.7)';blob(c,S*(.4+rnd()*.2),S*(.4+rnd()*.2),S*.07,rnd,7,.5);c.fill()}},'Магия');
inf('flesh-pillar','Столп из плоти',1,1,true,(c,S,rnd)=>{blob(c,S/2,S/2,S*.4,rnd,11,.3);c.fillStyle=rg(c,S*.45,S*.45,0,S*.42,['#d88a7a','#8a3a32','#3a0e0a']);c.fill();ink(c,S);c.stroke();for(let i=0;i<4;i++){const x=S*(.3+rnd()*.4),y=S*(.3+rnd()*.4);ell(c,x,y,S*.06,S*.04);c.fillStyle='#f0e8d0';c.fill();circ(c,x,y,S*.025);c.fillStyle='#c82020';c.fill()}},'Статуи');
inf('fissure','Огненная трещина',3,1,false,(c,S,rnd,p,W)=>{c.beginPath();c.moveTo(0,S*.5);for(let x=0;x<=W;x+=S*.25)c.lineTo(x,S*.5-S*(.08+rnd()*.12));for(let x=W;x>=0;x-=S*.25)c.lineTo(x,S*.5+S*(.08+rnd()*.12));c.closePath();c.fillStyle=lg(c,0,S*.3,0,S*.7,['#2a0a04','#ff9020','#2a0a04']);c.fill();ink(c,S,.02);c.stroke();glow(c,W/2,S/2,S*1.4,'rgba(255,90,20,.35)')},'Вода и лава','floor');
inf('sac-pit','Жертвенная яма',2,2,false,(c,S,rnd,p,W)=>{for(let i=0;i<10;i++){const a=i/10*PI*2;T.skull(c,S,W/2+Math.cos(a)*S*.85,W/2+Math.sin(a)*S*.85,.8)}circ(c,W/2,W/2,S*.7);c.fillStyle=rg(c,W/2,W/2,0,S*.7,['#ff6a10','#6e0a04','#000']);c.fill();ink(c,S);c.stroke()},'Ловушки','floor');
inf('demon-idol','Идол архидемона',2,2,true,(c,S,rnd,p,W)=>{const pts=[];for(let i=0;i<6;i++){const a=i/6*PI*2;pts.push([W/2+Math.cos(a)*W*.46,W/2+Math.sin(a)*W*.46])}poly(c,pts);c.fillStyle='#26252a';c.fill();ink(c,S);c.stroke();M.render&&0;c.save();c.translate(0,0);const fig=(x,y,k)=>{ell(c,x,y,S*.5*k,S*.3*k);c.fillStyle='#4a1410';c.fill();ink(c,S,.02);c.stroke();circ(c,x,y-S*.05,S*.22*k);c.fillStyle='#6e1e18';c.fill();c.stroke();[-1,1].forEach(s=>{c.beginPath();c.moveTo(x+s*S*.12,y-S*.2);c.quadraticCurveTo(x+s*S*.45,y-S*.5,x+s*S*.3,y-S*.75);c.lineWidth=S*.07;c.strokeStyle='#1a0808';c.stroke()})};fig(W/2,W/2,1.2);c.restore();c.fillStyle='#ff3a10';circ(c,W/2-S*.08,W/2-S*.1,S*.03);c.fill();circ(c,W/2+S*.08,W/2-S*.1,S*.03);c.fill();glow(c,W/2,W/2,S*1.1,'rgba(255,50,20,.25)')},'Статуи');
inf('burning-skulls','Горящие черепа',1,1,false,(c,S,rnd)=>{for(let i=0;i<4;i++){const x=S*(.25+rnd()*.5),y=S*(.25+rnd()*.5);T.skull(c,S,x,y,.9);flame(c,S,x,y-S*.08,1.2)}},'Свет');
inf('tormented-tree','Дерево страданий',2,2,true,(c,S,rnd,p,W)=>{c.fillStyle='rgba(60,10,8,.5)';blob(c,W/2,W/2,W*.45,rnd,11,.4);c.fill();const br=(x0,y0,a,l,w,d)=>{if(d<0)return;const x1=x0+Math.cos(a)*l,y1=y0+Math.sin(a)*l;c.strokeStyle='#1a0808';c.lineWidth=w;c.beginPath();c.moveTo(x0,y0);c.lineTo(x1,y1);c.stroke();if(d===0){T.skull(c,S,x1,y1,.5)}br(x1,y1,a-.5,l*.65,w*.6,d-1);br(x1,y1,a+.5,l*.65,w*.6,d-1)};for(let i=0;i<5;i++)br(W/2,W/2,i/5*PI*2,S*.35,S*.12,3)},'Природа','top');
