const elf=(id,n,th,w,h,solid,f,cat,layer)=>add('elf-'+id,n,cat||'Декор',th,w,h,solid,layer||'object',f);
elf('moonwell','Лунный колодец',['эльфы','фейвайлд'],2,2,true,(c,S,rnd,p,W)=>{for(let i=0;i<14;i++){const a=i/14*PI*2;c.save();c.translate(W/2+Math.cos(a)*S*.78,W/2+Math.sin(a)*S*.78);c.rotate(a);stoneBlock(c,S,-S*.1,-S*.14,S*.2,S*.28,P.marble,rnd);c.restore()}circ(c,W/2,W/2,S*.65);c.fillStyle=rg(c,W/2,W/2,0,S*.65,['#ffffff','#a0c8f0','#1a2a5a']);c.fill();ink(c,S);c.stroke();c.fillStyle='#ffffff';circ(c,W/2+S*.15,W/2-S*.1,S*.15);c.fill();c.fillStyle='#a0c8f0';circ(c,W/2+S*.2,W/2-S*.14,S*.13);c.fill();glow(c,W/2,W/2,S*1.2,'rgba(200,220,255,.4)')},'Вода и лава');
