elf('toadstool-table','Стол-поганка с табуретами-грибами',['фейвайлд'],2,2,true,(c,S,rnd,p,W)=>{const shr=(x,y,r)=>{shadow(c,S,()=>{circ(c,x,y,r);c.fillStyle='#000';c.fill()},.2);circ(c,x,y,r);c.fillStyle=rg(c,x-r*.3,y-r*.3,0,r,['#ff7a6a','#a01e18']);c.fill();ink(c,S,.02);c.stroke();c.fillStyle='#f4f0e6';for(let i=0;i<5;i++){circ(c,x+Math.cos(i*1.3)*r*.55,y+Math.sin(i*1.3)*r*.55,r*.13);c.fill()}};shr(W/2,W/2,S*.55);[[.25,.25],[1.75,.3],[.3,1.75],[1.7,1.7]].forEach(q=>shr(S*q[0],S*q[1],S*.2));T.mug(c,S,W/2-S*.15,W/2);T.mug(c,S,W/2+S*.15,W/2+S*.1)},'Мебель');
