elf('butterflies','Светящиеся бабочки',['фейвайлд','сад'],1,1,false,(c,S,rnd)=>{for(let i=0;i<5;i++){const x=S*(.2+rnd()*.6),y=S*(.2+rnd()*.6),col=['#ff9ae8','#9ae8ff','#fff09a'][i%3];glow(c,x,y,S*.12,'rgba(255,255,220,.5)');c.fillStyle=col;ell(c,x-S*.03,y,S*.03,S*.045,-.4);c.fill();ell(c,x+S*.03,y,S*.03,S*.045,.4);c.fill()}},'Природа','top');
