floor('flagstone','Пол: каменные плиты',['замок','подземелье','храм'],(c,S,rnd,W)=>{for(let i=0;i<4;i++)for(let j=0;j<4;j++)stoneBlock(c,S,i*S*.5+S*.01,j*S*.5+S*.01,S*.48,S*.48,rnd()<.3?P.dstone:P.stone,rnd)});
