floor('marble-check','Пол: мраморная шахматка',['дворец','храм','особняк'],(c,S,rnd,W)=>{for(let i=0;i<4;i++)for(let j=0;j<4;j++){c.fillStyle=(i+j)%2?'#2a2a30':'#e8e3d8';c.fillRect(i*S*.5,j*S*.5,S*.5,S*.5);c.strokeStyle=(i+j)%2?'rgba(120,120,140,.3)':'rgba(150,140,120,.35)';c.lineWidth=S*.008;c.beginPath();c.moveTo(i*S*.5+rnd()*S*.5,j*S*.5);c.quadraticCurveTo(i*S*.5+rnd()*S*.5,j*S*.5+S*.25,i*S*.5+rnd()*S*.5,j*S*.5+S*.5);c.stroke()}c.strokeStyle='rgba(0,0,0,.3)';c.lineWidth=S*.01;for(let i=0;i<=4;i++){c.beginPath();c.moveTo(i*S*.5,0);c.lineTo(i*S*.5,W);c.moveTo(0,i*S*.5);c.lineTo(W,i*S*.5);c.stroke()}});
