floor('dirt','Пол: утоптанная земля',['хижина','лагерь','шахта'],(c,S,rnd,W)=>{c.fillStyle='#6a5236';c.fillRect(0,0,W,W);for(let i=0;i<120;i++){circ(c,rnd()*W,rnd()*W,S*(.01+rnd()*.03));c.fillStyle=rnd()<.5?'rgba(40,28,15,.4)':'rgba(140,110,70,.4)';c.fill()}});
floor('herringbone','Пол: паркет ёлочкой',['особняк','дворец'],(c,S,rnd,W)=>{c.fillStyle=P.wood[1];c.fillRect(0,0,W,W);const L=S*.35,w=S*.12;for(let x=-L;x<W+L;x+=w*2)for(let y=-L;y<W+L;y+=L){[[x,y,PI/4],[x+w,y,-PI/4]].forEach(q=>{c.save();c.translate(q[0],q[1]);c.rotate(q[2]);c.fillStyle=P.wood[1+((Math.abs(x+y)/w|0)%3)];c.fillRect(0,0,L,w);c.strokeStyle='rgba(20,12,6,.5)';c.lineWidth=S*.008;c.strokeRect(0,0,L,w);c.restore()})}});
